def smoothknots(knots,vals):
 def f(t):
  for i in range(len(knots)-1):
   if knots[i]<=t<=knots[i+1]:
    u=(t-knots[i])/(knots[i+1]-knots[i]);return vals[i]+(vals[i+1]-vals[i])*(3*u*u-2*u**3)
  return vals[-1]
 return f
